217	  // appears right under the composer instead of dropping into a random (shortest) column.
218	  const firstMemo = sortedMemoList[0];
219	  const priorityKey = newMemoName && firstMemo?.name === newMemoName ? getMemoKey(firstMemo) : undefined;
220	
221	  // Stable reference so MentionResolutionProvider's memo (keyed on the array) actually holds.
222	  const contents = useMemo(() => sortedMemoList.map((memo) => memo.content), [sortedMemoList]);
223	
224	  const emptyPlaceholder =
225	    !isFetchingNextPage && !hasNextPage && sortedMemoList.length === 0 ? (
226	      <Placeholder variant="empty" message={t("message.no-data")} className="w-full" />
227	    ) : null;
228	
229	  // Column one is the action column: the composer and any active filters head it, and the
230	  // empty state follows them. The newest memo also lands directly beneath them (priorityKey
231	  // above). Every vertical seam inside the stack uses GRID_GAP so y-spacing matches the
232	  // grid's x-spacing exactly.
233	  const hasFilters = filters.length > 0;
234	  const gridLeading =
235	    memoEditor || hasFilters || emptyPlaceholder ? (
236	      <div className="flex w-full flex-col" style={{ gap: GRID_GAP }}>
237	        {memoEditor}
238	        <MemoFilters />
239	        {emptyPlaceholder}
240	      </div>
241	    ) : undefined;
242	
243	  // Pagination controls are identical across both layouts.
244	  const footer = (
245	    <>
246	      {isFetchingNextPage && <Loader />}
247	      {!isFetchingNextPage && (hasNextPage || sortedMemoList.length > 0) && (
248	        <div className="w-full opacity-70 flex flex-row justify-center items-center my-4">
249	          <BackToTop />
250	        </div>
251	      )}
252	    </>
253	  );
254	
255	  const children = (
256	    <MentionResolutionProvider contents={contents}>
257	      <div ref={layoutMeasureRef} className="w-full">
258	        <div className={cn("flex flex-col justify-start w-full mx-auto", useGrid ? "max-w-none" : "max-w-2xl")}>
259	          {/* During initial load, show the spinner only after the delay; render nothing before then to avoid a flash. */}
260	          {isLoading ? (
261	            showLoader ? (
262	              <Loader />
263	            ) : null
264	          ) : useGrid ? (
265	            <>
266	              <ColumnGrid
267	                items={sortedMemoList}
268	                getKey={getMemoKey}
269	                renderItem={(memo) => props.renderer(memo, { compact: effectiveCompact })}
270	                estimateHeight={estimateMemoCardHeight}
271	                leading={gridLeading}
272	                priorityKey={priorityKey}
273	                maxColumns={maxColumns}
274	                maxColumnWidth={MAX_COLUMN_WIDTH}
275	              />
276	              {footer}
277	            </>
278	          ) : (
279	            <>
280	              {memoEditor}
281	              <MemoFilters className="mb-2" />
282	              {sortedMemoList.map((memo) => props.renderer(memo, { compact: effectiveCompact }))}
283	              {emptyPlaceholder}
284	              {footer}
285	            </>
286	          )}
287	        </div>
288	      </div>
289	    </MentionResolutionProvider>
290	  );
291	
292	  return children;
293	};
